<h1 align="center">Alexa APIs for Node.js</h1>
<p align="center">
  A set of APIs that help you build Alexa Skills using Node.js
</p>
<p align="center">
  <a href="#installation">Installation</a> •
  <a href="#usage">Usage</a> •
  <a href="#features">Features</a> •
  <a href="#contribute">Contribute</a> •
  <a href="#license">License</a>
</p>

## Installation

Install the module from npm:

```
npm install alexa-apis-for-nodejs
```

## Usage

The Alexa API for Node.js is a set of APIs that help you build Alexa Skills using Node.js.

### Basic Usage

```javascript
// Load the Alexa API
const Alexa = require('alexa-apis-for-nodejs');

// Define the Skill's response
const speechOutput = 'Hello World!';

// Create the response object
const response = Alexa.createResponse();

// Send the response
response.speak(speechOutput).send();
```

### Request Handling

```javascript
// Load the Alexa API
const Alexa = require('alexa-apis-for-nodejs');

// Handle the request
function handleRequest(request) {
  // Define the Skill's response
  const speechOutput = 'Hello World!';

  // Create the response object
  const response = Alexa.createResponse();

  // Send the response
  response.speak(speechOutput).send();
}

// Export the request handler
module.exports = handleRequest;
```

### Custom Intents

```javascript
// Load the Alexa API
const Alexa = require('alexa-apis-for-nodejs');

// Handle the request
function handleRequest(request) {
  // Define the Skill's response
  const speechOutput = 'Hello World!';

  // Create the response object
  const response = Alexa.createResponse();

  // Send the response
  response.speak(speechOutput).send();
}

// Export the request handler
module.exports = handleRequest;
```

### Custom Slots

```javascript
// Load the Alexa API
const Alexa = require('alexa-apis-for-nodejs');

// Handle the request
function handleRequest(request) {
  // Define the Skill's response
  const speechOutput = 'Hello World!';

